"""Parse json files generated by SuprConGPU."""

# Built-in modules and third-party libraries.
import os
import sys
import json
import numpy as np
from pathlib import Path

# Custom libraries.
sys.path.insert(0, "../../")
from python_libraries.file_io import utils
from python_libraries.settings import configuration

# Global settings.

# -----------------------------------------------------------------------------
# PARSE GENERAL JSON
# -----------------------------------------------------------------------------
# General parser for json files: return result as dictionary.
def parse_general_json(file_path: str) -> dict:
    # Check that file exists and is readable: exit on failure.
    utils.check_file(file_path)

    # Storage for data dict.
    data = {}

    # Attempt to parse JSON file.
    with open(file_path) as json_file:
        data_string_json = json_file.read()
        data = json.loads(data_string_json)

    return data


# -----------------------------------------------------------------------------
# WRAPPERS
# -----------------------------------------------------------------------------
# Parse simulation parameters.
def parse_config(base_path: str) -> dict:
    # Construct full file path.
    data_path = Path(base_path) / configuration.filenames["config"]

    return parse_general_json(data_path)


# Parse "internal parameters" generated by the SuprConGPU framework.
def parse_internal_parameters(base_path: str) -> dict:
    # Construct full file path.
    data_path = Path(base_path) / configuration.filenames["internal_parameters"]

    return parse_general_json(data_path)


# Parse scalar results (e.g. area-averaged observables).
def parse_scalar_results(base_path: str) -> dict:
    # Construct full file path.
    data_path = Path(base_path) / configuration.filenames["results"]

    return parse_general_json(data_path)


# Parse post-processing data (e.g. DOS information).
def parse_post_processing(base_path: str) -> dict:
    # Construct full file path.
    data_path = Path(base_path) / configuration.filenames["post_processing"]

    return parse_general_json(data_path)